CELLS = [('markdown', '# Gemini Table Probe - Burnaby R1\n\nThis notebook only tests table-style evidence batches. It does not run the full extraction pipeline.\n\nFlow:\n1. Load existing Burnaby `table_rule_batches.json` if available.\n2. Otherwise rebuild table batches from `evidence_units.json` and `prototype_target_aware_helpers.py`.\n3. Send the full table inventory to Gemini Flash-Lite in one free-tier-friendly request by default.\n4. Save raw Gemini responses and parsed rules for inspection.\n\nSet `GEMINI_API_KEY` in your environment before running, or paste it into the config cell temporarily.'), ('code', "import json\nimport os\nimport re\nimport time\nfrom pathlib import Path\n\nimport pandas as pd\nimport requests\nfrom tqdm.auto import tqdm\n\n# Locate code/prototype_pipeline regardless of kernel cwd.\ndef locate_prototype_dir():\n    cwd = Path.cwd()\n    for d in [cwd, *cwd.parents]:\n        candidate = d / 'code' / 'prototype_pipeline'\n        if (candidate / 'prototype_rule_extraction_pipeline.ipynb').exists():\n            return candidate.resolve()\n        if (d / 'prototype_rule_extraction_pipeline.ipynb').exists():\n            return d.resolve()\n    return cwd.resolve()\n\nPROTOTYPE_DIR = locate_prototype_dir()\nos.chdir(PROTOTYPE_DIR)\n\nimport sys\nimport importlib\nif str(PROTOTYPE_DIR) not in sys.path:\n    sys.path.insert(0, str(PROTOTYPE_DIR))\nimport prototype_target_aware_helpers as helpers\nimportlib.reload(helpers)\nfrom prototype_target_aware_helpers import *\n\nprint('PROTOTYPE_DIR:', PROTOTYPE_DIR)"), ('markdown', '## Config'), ('code', "TARGET_CITY = 'burnaby'\nRUN_ID = f'prototype_{TARGET_CITY}_rule_pipeline'\nRULE_OUTPUT_DIR = PROTOTYPE_DIR / 'outputs' / TARGET_CITY / RUN_ID / '03_rules'\nPROBE_OUTPUT_DIR = PROTOTYPE_DIR / 'outputs' / TARGET_CITY / RUN_ID / '04_gemini_table_probe'\nPROBE_OUTPUT_DIR.mkdir(parents=True, exist_ok=True)\n\n# Cheapest/free-tier-friendly default: Flash-Lite with 2-3 semantic chunks.\n# This avoids both 17 tiny calls and one giant response that gets truncated.\nGEMINI_MODEL = 'gemini-2.5-flash-lite'\nGEMINI_API_KEY = os.getenv('GEMINI_API_KEY', '')\n# GEMINI_API_KEY = 'PASTE_KEY_HERE'  # optional local override; avoid committing keys.\n\nREQUEST_TIMEOUT = 180\nTEMPERATURE = 0.0\nMAX_OUTPUT_TOKENS = 12000\n\n# Free-tier safe mode:\n# - 'semantic_chunks': 2-3 large calls grouped by table meaning. Recommended.\n# - 'single': one call for all rows; cheapest but may truncate.\n# - 'chunks': mechanical chunks for debugging only.\nGEMINI_CALL_MODE = 'semantic_chunks'\nCHUNK_SIZE = 8\n\n# Optional local debug limit before the single request is built.\nMAX_BATCHES = None\n\nprint('RULE_OUTPUT_DIR:', RULE_OUTPUT_DIR)\nprint('PROBE_OUTPUT_DIR:', PROBE_OUTPUT_DIR)\nprint('Gemini model:', GEMINI_MODEL)\nprint('API key set:', bool(GEMINI_API_KEY))\nprint('Gemini call mode:', GEMINI_CALL_MODE)\n"), ('markdown', '## Load Or Rebuild Table Batches'), ('code', "batches_path = RULE_OUTPUT_DIR / 'table_rule_batches.json'\ngroups_path = RULE_OUTPUT_DIR / 'table_rule_groups.json'\nevidence_units_path = RULE_OUTPUT_DIR / 'evidence_units.json'\n\nif batches_path.exists():\n    table_batches = json.loads(batches_path.read_text(encoding='utf-8'))\n    print(f'Loaded table batches: {len(table_batches)} from {batches_path}')\nelse:\n    evidence_units = json.loads(evidence_units_path.read_text(encoding='utf-8'))\n    # Re-run current admission in case evidence_units were produced by an older helper.\n    doc_config = {'city': 'Burnaby', 'building_type': 'Rear Principal Building'}\n    enriched = []\n    for ev in evidence_units:\n        ev = dict(ev)\n        ev.update(classify_evidence_unit_pre_llm(ev, doc_config))\n        enriched.append(ev)\n    groups = build_table_rule_groups(enriched)\n    table_batches = []\n    for group in groups:\n        table_batches.extend(split_table_group_into_extraction_batches(group, max_rows=2))\n    print(f'Rebuilt table batches: {len(table_batches)}')\n\nif MAX_BATCHES is not None:\n    table_batches = table_batches[:MAX_BATCHES]\n    print(f'Limited to first {len(table_batches)} batches')\n\npd.DataFrame([\n    {\n        'batch_id': b.get('batch_id'),\n        'group_title': b.get('group_title'),\n        'rows': len(b.get('rows', [])),\n        'row_labels': ' | '.join(r.get('row_label', '') for r in b.get('rows', [])),\n    }\n    for b in table_batches\n]).head(30)"), ('markdown', '## Gemini Prompt'), ('code', 'def compact_batch_for_gemini(batch, index):\n    # Use a unique probe_batch_id because source batch_id may repeat across table groups.\n    return {\n        \'probe_batch_id\': f\'probe_batch_{index:03d}\',\n        \'source_batch_id\': batch.get(\'batch_id\'),\n        \'group_title\': batch.get(\'group_title\'),\n        \'operator_hint\': batch.get(\'operator_hint\'),\n        \'rows\': [\n            {\n                \'evidence_id\': r.get(\'evidence_id\'),\n                \'row_label\': r.get(\'row_label\'),\n                \'row_text\': r.get(\'text\'),\n            }\n            for r in batch.get(\'rows\', [])\n        ],\n    }\n\n\ndef compact_inventory_for_gemini(batches):\n    return [compact_batch_for_gemini(batch, i) for i, batch in enumerate(batches, start=1)]\n\n\ndef build_gemini_table_inventory_prompt(batches):\n    compact = json.dumps(compact_inventory_for_gemini(batches), ensure_ascii=False)\n    return f\'\'\'Extract Burnaby R1 zoning table rules. Return JSON only.\n\nGoal:\n- Extract generic building/lot/yard rules for permitted dwelling units, lot area,\n  lot coverage, impervious surfaces, height, storeys, setbacks, separation,\n  access, parking, and fire access.\n- Use all provided table rows in one pass. Do not require laneway terms.\n\nRules:\n- Extract one atomic rule per meaningful value in row_text.\n- Use the exact evidence_id of the row containing the value.\n- Use group_title/operator_hint to infer <= for Maximum and >= for Minimum.\n- Split multiple values in one row.\n- Preserve row/column meaning in condition when visible, e.g. unit count, lot size,\n  roof type, yard type, transit-network condition.\n- Put "except ..." text in exception.\n- Do not invent values not visible in row_text.\n\nReturn this exact JSON shape:\n{{\n  "rules": [\n    {{\n      "evidence_id": "...",\n      "rule_key": "...",\n      "subject": "...",\n      "operator": "<= / >= / =",\n      "value": "...",\n      "unit": "...",\n      "condition": "...",\n      "exception": null\n    }}\n  ],\n  "skipped_rows": [\n    {{"evidence_id": "...", "reason": "no_rule/header_only/duplicate/unclear"}}\n  ]\n}}\n\nTable inventory JSON:\n{compact}\n\'\'\'\n\n\ndef build_gemini_table_chunk_prompt(batch_chunk):\n    # Same schema as the single-call prompt, but for a smaller chunk.\n    return build_gemini_table_inventory_prompt(batch_chunk)\n\n\nprint(build_gemini_table_inventory_prompt(table_batches)[:2500])\n'), ('markdown', '## Gemini API Call'), ('code', "def call_gemini(prompt):\n    if not GEMINI_API_KEY:\n        raise RuntimeError('GEMINI_API_KEY is not set. Set env var or paste it in the config cell.')\n    url = f'https://generativelanguage.googleapis.com/v1beta/models/{GEMINI_MODEL}:generateContent'\n    payload = {\n        'contents': [{'role': 'user', 'parts': [{'text': prompt}]}],\n        'generationConfig': {\n            'temperature': TEMPERATURE,\n            'maxOutputTokens': MAX_OUTPUT_TOKENS,\n            'responseMimeType': 'application/json',\n        },\n    }\n    resp = requests.post(\n        url,\n        params={'key': GEMINI_API_KEY},\n        json=payload,\n        timeout=REQUEST_TIMEOUT,\n    )\n    resp.raise_for_status()\n    data = resp.json()\n    parts = data.get('candidates', [{}])[0].get('content', {}).get('parts', [])\n    return ''.join(p.get('text', '') for p in parts), data\n"), ('markdown', '## Run Table Probe'), ('code', 'probe_logs = []\nparsed_rules = []\nparse_failures = []\n\n\ndef parse_gemini_rules(raw_text, fallback_id):\n    obj, err = parse_llm_json_response(raw_text)\n    if obj is None:\n        rules, skipped, status, parse_error = parse_minimal_table_response(raw_text, fallback_id)\n        return rules, skipped, status, parse_error\n    if isinstance(obj, dict):\n        return (\n            [r for r in obj.get(\'rules\', []) if isinstance(r, dict)],\n            [r for r in obj.get(\'skipped_rows\', []) if isinstance(r, dict)],\n            \'success_json\',\n            None,\n        )\n    if isinstance(obj, list):\n        return [r for r in obj if isinstance(r, dict)], [], \'success_list\', None\n    return [], [], \'invalid_top_level\', f\'unexpected type {type(obj).__name__}\'\n\n\ndef enrich_gemini_rules(rules, batches):\n    # Match by evidence_id instead of batch_id; evidence ids are stable and unique.\n    evidence_to_batch = {}\n    evidence_to_row = {}\n    for batch in batches:\n        for row in batch.get(\'rows\', []):\n            eid = row.get(\'evidence_id\')\n            if eid:\n                evidence_to_batch[eid] = batch\n                evidence_to_row[eid] = row\n    enriched = []\n    for rule in rules:\n        eid = rule.get(\'evidence_id\')\n        batch = evidence_to_batch.get(eid)\n        if not batch:\n            continue\n        row_lookup = {eid: evidence_to_row[eid]}\n        enriched.append(enrich_minimal_table_rule(rule, batch, row_lookup, {\'building_type\': \'Rear Principal Building\'}, \'R1\'))\n    return enriched\n\n\ndef build_semantic_call_chunks(batches):\n    groups = {\n        \'development_coverage_height\': [],\n        \'setbacks_separation\': [],\n        \'other_tables\': [],\n    }\n    for batch in batches:\n        title = normalize_text(batch.get(\'group_title\', \'\'))\n        rows = normalize_text(\' \'.join(str(r.get(\'row_label\', \'\')) + \' \' + str(r.get(\'text\', \'\')) for r in batch.get(\'rows\', [])))\n        hay = f\'{title} {rows}\'\n        if any(term in hay for term in [\'setback\', \'yard\', \'separation\', \'between front\', \'between rear\']):\n            groups[\'setbacks_separation\'].append(batch)\n        elif any(term in hay for term in [\'development regulations\', \'lot coverage\', \'impervious\', \'height\', \'storey\', \'storeys\', \'lot area\', \'dwelling units\']):\n            groups[\'development_coverage_height\'].append(batch)\n        else:\n            groups[\'other_tables\'].append(batch)\n    return [(name, chunk) for name, chunk in groups.items() if chunk]\n\n\nif GEMINI_CALL_MODE == \'single\':\n    call_chunks = [(\'all_tables\', table_batches)]\nelif GEMINI_CALL_MODE == \'semantic_chunks\':\n    call_chunks = build_semantic_call_chunks(table_batches)\nelse:\n    call_chunks = [\n        (f\'chunk_{i // CHUNK_SIZE + 1:03d}\', table_batches[i:i + CHUNK_SIZE])\n        for i in range(0, len(table_batches), CHUNK_SIZE)\n    ]\n\nprint(\'Gemini call chunks:\')\nfor call_id, chunk in call_chunks:\n    print(f\'  {call_id}: batches={len(chunk)} rows={sum(len(b.get("rows", [])) for b in chunk)}\')\n\nfor call_id, batch_chunk in tqdm(call_chunks, desc=\'Gemini table inventory calls\'):\n    prompt = build_gemini_table_inventory_prompt(batch_chunk)\n    started = time.time()\n    raw_text = \'\'\n    call_error = None\n    parse_status = \'not_run\'\n    parse_error = None\n    rules = []\n    skipped = []\n    try:\n        raw_text, raw_api = call_gemini(prompt)\n        rules, skipped, parse_status, parse_error = parse_gemini_rules(raw_text, call_id)\n        parsed_rules.extend(enrich_gemini_rules(rules, batch_chunk))\n    except Exception as e:\n        call_error = f\'{type(e).__name__}: {e}\'\n    seconds = time.time() - started\n    if parse_status not in {\'success_json\', \'success_rules\', \'success_partial_recovery\', \'success_list\'} and raw_text:\n        parse_failures.append({\n            \'call_id\': call_id,\n            \'parse_status\': parse_status,\n            \'parse_error\': parse_error,\n            \'raw_excerpt\': raw_text[:2000],\n        })\n    probe_logs.append({\n        \'call_id\': call_id,\n        \'batch_count\': len(batch_chunk),\n        \'row_count\': sum(len(b.get(\'rows\', [])) for b in batch_chunk),\n        \'rule_count\': len(rules),\n        \'skipped_count\': len(skipped),\n        \'parse_status\': parse_status,\n        \'parse_error\': parse_error,\n        \'call_error\': call_error,\n        \'seconds\': seconds,\n        \'raw_response\': raw_text,\n    })\n\nlogs_df = pd.DataFrame(probe_logs)\nrules_df = pd.DataFrame(parsed_rules)\nfailures_df = pd.DataFrame(parse_failures)\n\ndisplay(logs_df)\ndisplay(rules_df.head(80))\nprint(\'Gemini API calls:\', len(call_chunks))\nprint(\'Parsed rules:\', len(rules_df))\n'), ('markdown', '## Save Outputs'), ('code', "logs_path = PROBE_OUTPUT_DIR / 'gemini_table_probe_logs.csv'\nlogs_json_path = PROBE_OUTPUT_DIR / 'gemini_table_probe_logs.json'\nrules_path = PROBE_OUTPUT_DIR / 'gemini_table_rules.csv'\nrules_json_path = PROBE_OUTPUT_DIR / 'gemini_table_rules.json'\nfailures_path = PROBE_OUTPUT_DIR / 'gemini_table_parse_failures.csv'\nfailures_json_path = PROBE_OUTPUT_DIR / 'gemini_table_parse_failures.json'\n\nlogs_df.to_csv(logs_path, index=False, encoding='utf-8-sig')\nlogs_json_path.write_text(logs_df.to_json(orient='records', force_ascii=False, indent=2), encoding='utf-8')\nrules_df.to_csv(rules_path, index=False, encoding='utf-8-sig')\nrules_json_path.write_text(rules_df.to_json(orient='records', force_ascii=False, indent=2), encoding='utf-8')\nfailures_df.to_csv(failures_path, index=False, encoding='utf-8-sig')\nfailures_json_path.write_text(failures_df.to_json(orient='records', force_ascii=False, indent=2), encoding='utf-8')\n\nprint('Saved:', logs_path)\nprint('Saved:', rules_path)\nprint('Saved:', failures_path)\nprint('Total rules:', len(rules_df))")]

